begin;
create function private.create_purchase_condition_version(p_company_id uuid,p_stock_id uuid,p_expected_version integer,p_expected_purchase_price_ore bigint,p_expected_calculation_version bigint,p_expected_vehicle_id uuid,p_supplier_kind text,p_supplier_name text,p_supplier_organisation_number text,p_acquired_on date,p_document_reference text,p_checked_on date,p_mileage_km integer,p_conditions jsonb,p_repair_estimate_ore bigint,p_request_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a uuid;r text;s public.stock_items;v public.vehicles;t private.purchase_condition_versions;old private.purchase_condition_audit;p jsonb;receipt jsonb;snap jsonb;latest integer;today date:=(clock_timestamp() at time zone 'Europe/Stockholm')::date;begin
 select actor,actor_role into a,r from private.purchase_condition_access(p_company_id);
 if p_request_id is null or p_expected_version is null or p_expected_version not between 0 and 2147483646 or p_expected_purchase_price_ore is null or p_expected_purchase_price_ore<0 or p_expected_calculation_version is null or p_expected_calculation_version<1 or p_expected_vehicle_id is null or p_supplier_kind is null or p_supplier_kind not in ('person','business') or p_supplier_name is null or length(p_supplier_name) not between 2 and 160 or p_supplier_name<>btrim(p_supplier_name) or p_supplier_name ~ '[[:cntrl:]]' or (p_supplier_kind='person' and p_supplier_organisation_number is not null) or(p_supplier_organisation_number is not null and p_supplier_organisation_number !~ '^[0-9]{10}$') or p_acquired_on is null or p_acquired_on<date '1900-01-01' or p_checked_on is null or p_checked_on<date '1900-01-01' or(p_document_reference is not null and(length(p_document_reference) not between 1 and 160 or p_document_reference<>btrim(p_document_reference) or p_document_reference ~ '[[:cntrl:]]')) or p_mileage_km is null or p_mileage_km not between 0 and 2000000 or not private.purchase_condition_checks(p_conditions) or(p_repair_estimate_ore is not null and p_repair_estimate_ore not between 0 and 999999999999) then raise exception 'Invalid purchase/condition underlag' using errcode='22023';end if;
 select * into s from public.stock_items where company_id=p_company_id and id=p_stock_id for update;
 if not found then raise exception 'Stock access denied' using errcode='42501';end if;
 p:=jsonb_build_object('stockId',p_stock_id,'companyId',p_company_id,'expectedVersion',p_expected_version,'expectedPurchasePriceOre',p_expected_purchase_price_ore::text,'expectedCalculationVersion',p_expected_calculation_version::text,'expectedVehicleId',p_expected_vehicle_id,'supplierKind',p_supplier_kind,'supplierName',p_supplier_name,'supplierOrganisationNumber',p_supplier_organisation_number,'acquiredOn',p_acquired_on,'documentReference',p_document_reference,'checkedOn',p_checked_on,'mileageKm',p_mileage_km,'conditions',p_conditions,'repairEstimateOre',p_repair_estimate_ore::text);
 perform pg_advisory_xact_lock(hashtextextended(a::text||p_request_id::text,0));
 select * into old from private.purchase_condition_audit where actor_user_id=a and request_id=p_request_id;
 if found then if old.payload is distinct from p then raise exception 'Request conflict' using errcode='40001';end if;return old.receipt;end if;
 select coalesce(max(version),0) into latest from private.purchase_condition_versions where company_id=p_company_id and stock_id=p_stock_id;
 if latest<>p_expected_version or s.purchase_price_ore<>p_expected_purchase_price_ore or s.calculation_version<>p_expected_calculation_version or s.vehicle_id<>p_expected_vehicle_id or s.status not in ('available','reserved') then raise exception 'Source/version conflict' using errcode='40001';end if;
 if p_acquired_on>today or p_checked_on>today then raise exception 'Future underlag date' using errcode='22023';end if;
 select * into v from public.vehicles where company_id=p_company_id and id=s.vehicle_id for share;
 if not found then raise exception 'Vehicle access denied' using errcode='42501';end if;
 select jsonb_build_object('company',jsonb_build_object('name',name,'organisationNumber',organisation_number),'basis',private.purchase_condition_basis(s,v)) into snap from public.companies where id=p_company_id;
 snap:=snap||(p-array['stockId','companyId','expectedVersion','expectedPurchasePriceOre','expectedCalculationVersion','expectedVehicleId']);
 insert into private.purchase_condition_versions(company_id,stock_id,version,snapshot,created_by)values(p_company_id,p_stock_id,latest+1,snap,a) returning * into t;
 receipt:=jsonb_build_object('companyId',p_company_id,'actorUserId',a,'requestId',p_request_id,'purchaseCondition',private.purchase_condition_json(t));
 insert into private.purchase_condition_audit(company_id,actor_user_id,request_id,payload,receipt)values(p_company_id,a,p_request_id,p,receipt);return receipt;
end$$;
revoke all on function private.create_purchase_condition_version(uuid,uuid,integer,bigint,bigint,uuid,text,text,text,date,text,date,integer,jsonb,bigint,uuid) from public,anon,authenticated,service_role;
commit;
